#nora-statusbar {
  visibility: visible !important;
  display: flex;
  align-items: center;
  width: 100%;
  border-top: 1px solid var(--chrome-content-separator-color);
  background: var(--panel-sidebar-background-color) !important;

  :root[inFullscreen]:not([macOSNativeFullscreen])
    &:not([fullscreentoolbar="true"]) {
    visibility: collapse !important;
  }

  :root[customizing] & {
    display: inherit !important;
  }

  #statuspanel-label {
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    color: inherit !important;
  }
}

#nora-statusbar #status-text {
  padding-inline: 8px; /* px-2 */
  overflow: hidden;
  order: 1;
}

#toggle_nora-statusbar {
  display: none !important;
}
